      var key = '__uz_' + a, tk = '__tr_' + a, v = el.getAttribute(a);
      if (el[tk] === undefined || v !== el[tk]) el[key] = v;
      var out = swap(el[key], cur);
      el[tk] = out;
      if (v !== out) el.setAttribute(a, out);
